import{localEncounters}from './encounters.js';
import{physiologyStep}from './physiology.js';
import{initFamily,syncFamily}from './family.js';
import{speciesOf}from './species.js';
const clamp=x=>Math.max(0,Math.min(100,x));
export function initLifeState(s){speciesOf(s);s.species??='dog';s.caregiverId??=(s.home==='street'?null:'carer-initial');s.mode??='intervene';s.needs??={hunger:15,thirst:12,fatigue:20,happiness:Math.round(s.comfort),strain:0};s.episodes??=[];s.relations??=[];s.resolvedDecisions??=[];s.decisionSerial??=0;s.birthplace??={country:s.country.id,countryName:s.country.name,place:s.worldModel.origin.label};for(const [k,salt]of [['independence',31],['adaptability',32]])s.worldModel.traits[k]??=15+((s.seed*17+salt*19)>>>0)%76;s.inborn??={...s.worldModel.traits};s.milestones.ears??=14+s.seed%6;s.reproduction??={matureAt:180+(s.seed%91)+(s.appearance.adultKg>30?90:0)};initFamily(s);syncRelations(s);syncFamily(s);}
function relation(id,kind,name,area){return {id,kind,name,area,familiarity:0,trust:0,caution:30,conflict:0,contacts:0,lastContact:null,active:true};}
export function syncRelations(s){if(!s.relations)return;const put=(id,kind,name)=>{let r=s.relations.find(r=>r.id===id);if(!r){r=relation(id,kind,name,s.areaId);s.relations.push(r)}return r};const origin=s.worldModel.origin;
if(origin.mother){const r=put('mother','mother','어미');r.name='어미';r.active=s.day<90&&!s.lastAreaChange;r.familiarity=Math.max(r.familiarity,s.day<90?Math.min(95,30+s.day):r.familiarity);r.trust=Math.max(r.trust,60)}
for(let i=1;i<(origin.mother?s.worldModel.litter:0);i++){const r=put('sibling-'+i,'sibling',`${i}번째 형제`);r.active=s.day<90&&!s.lastAreaChange;r.familiarity=Math.max(r.familiarity,Math.min(90,s.day+10))}
if(s.home!=='street'&&!s.story.lost){s.caregiverId??='carer-'+s.areaId;const r=put(s.caregiverId,'caregiver',s.home==='family'?'함께 사는 사람':'돌보는 사람');r.area=s.areaId;r.familiarity=Math.max(r.familiarity,s.familyBond);r.trust=s.trust;r.active=true;}
for(const r of s.relations){if(r.kind==='father')r.active=!!s.chronicle?.birth.father.together&&s.day<90&&!s.lastAreaChange;if(['caregiver','visitor','dog'].includes(r.kind))r.active=r.area===s.areaId&&!s.story.lost&&(r.kind!=='caregiver'||s.home!=='street'&&r.id===s.caregiverId)}
if(localEncounters(s)){const r=put('visitor-'+(s.visitorArea||s.areaId),'visitor','자주 찾아오는 사람');r.familiarity=Math.min(95,localEncounters(s)*18);r.trust=s.trust;r.contacts=localEncounters(s);}
for(const r of s.relations){if(r.active&&['mother','father','sibling','caregiver'].includes(r.kind)&&r.lastContact!==s.day){r.contacts++;r.lastContact=s.day;}}
if(s.friend.met){const f=s.friend,r=put(f.id,'dog',f.name);r.familiarity=Math.min(100,f.meetings*12);r.trust=f.bond;r.contacts=f.meetings;r.lastContact=f.lastMet;r.caution=f.caution??Math.max(0,50-f.bond/2);r.conflict=f.conflict||0;}
}
export function memoryInfluence(s,target){const now=s.day;return Math.max(-15,Math.min(15,(s.episodes||[]).filter(m=>m.target===target).reduce((v,m)=>v+m.valence*m.intensity*Math.exp(-(now-m.day)/m.persistence)*.08,0)));}
export function recordExperience(s,p,option,before){initLifeState(s);const delta={};for(const k of ['health','comfort','trust','stress','familyBond','dogBond','hunger','thirst','fatigue','happiness']){const d=Math.round((s.needs[k]??s[k]??0)-(before[k]||0));if(d)delta[k]=d}const target=p.context?.actor|| (p.id==='pain-response'?'veterinary-care':p.id==='companion-time'?s.reproduction.companion?.id||'companion':p.id==='litter-care'?'offspring':p.id==='dog-meet'?s.friend.id:p.id==='encounter'?'visitor':p.id==='health-response'?'care':s.caregiverId||'caregiver');const valence=delta.stress>0?-1:delta.stress<0?1:delta.trust>0||delta.comfort>0||delta.dogBond>0||delta.familyBond>0||delta.hunger<0||delta.thirst<0||delta.fatigue<0?1:0;const narrative=s.log.slice(before.logLength).filter(e=>e.id!=='choice').map(e=>e.text).join(' ');const id=p.uid||`${p.id}:${s.day}:${before.logLength}`;s.episodes.push({id,kind:p.id,day:s.day,target,valence,intensity:Math.min(30,5+Object.values(delta).reduce((a,b)=>a+Math.abs(b),0)),persistence:valence<0?240:180,action:option,domain:p.context?.memoryDomain||(p.id==='dog-meet'?'canine-social':null),sourceRecord:p.context?.sourceRecord??null,delta,followup:[...s.lifeEvents.followups.filter(f=>f.day>=s.day).map(f=>({id:f.id,day:f.day})),...(s.threads?.arcs||[]).filter(a=>a.stage==='waiting').map(a=>({id:a.id,day:a.next})),...(s.journeys?.arcs||[]).filter(a=>a.status==='waiting').map(a=>({id:a.id,day:a.next}))],text:narrative,...(p.context?.cause?{cause:p.context.cause,actorId:p.context.actor,place:p.context.place,area:p.context.area,semantic:p.semantic||p.context.semantic||null}: {})});s.presentation={id,day:s.day,action:option,text:narrative||'몸을 움직인 뒤 잠시 쉬며 주변을 살핀다.',delta};syncRelations(s);}
// One day is a compressed cycle with automatic feeding, drinking and rest.
// These 0–100 need scores are game states, not physical intake/temperature measurements.
export function needsStep(s,log){initLifeState(s);physiologyStep(s,log)}
export function validateLifeState(s){if(s.behavior&&(!['food','water','rest','avoid','social','explore'].includes(s.behavior.goal)||!Number.isFinite(s.behavior.activity)||s.behavior.activity<0||s.behavior.activity>2||!Array.isArray(s.behavior.history)))throw Error('손상된 행동 상태');if(s.development&&(!Array.isArray(s.development.historicalUnknown)||!s.development.historicalUnknown.every(x=>typeof x==='string')))throw Error('손상된 발달 상태');if(s.species&&s.species!=='dog')throw Error('지원하지 않는 동물 종');if(s.mode&&!['observe','intervene'].includes(s.mode))throw Error('손상된 진행 모드');if(s.needs&&!['hunger','thirst','fatigue','happiness'].every(k=>Number.isFinite(s.needs[k])&&s.needs[k]>=0&&s.needs[k]<=100))throw Error('손상된 상태 기록');if(s.episodes&&(!Array.isArray(s.episodes)||!s.episodes.every(m=>typeof m.id==='string'&&Number.isFinite(m.day)&&typeof m.target==='string'&&Number.isFinite(m.intensity)&&Number.isFinite(m.persistence)&&m.persistence>0&&Number.isFinite(m.valence))))throw Error('손상된 기억 기록');if(s.episodes?.some(m=>m.domain!=null&&!['canine-social','caregiver-contact','movement'].includes(m.domain)||m.sourceRecord!=null&&(!Number.isInteger(m.sourceRecord)||m.sourceRecord<0||!s.log[m.sourceRecord]||s.log[m.sourceRecord].day>m.day)))throw Error('손상된 인과 기억 기록');if(s.relations&&(!Array.isArray(s.relations)||!s.relations.every(r=>typeof r.id==='string'&&typeof r.name==='string'&&['familiarity','trust','caution','conflict','contacts'].every(k=>Number.isFinite(r[k])))))throw Error('손상된 관계 기록');if(s.presentation&&(typeof s.presentation.id!=='string'||typeof s.presentation.text!=='string'||!Number.isInteger(s.presentation.day)||!s.presentation.delta||typeof s.presentation.delta!=='object'))throw Error('손상된 결과 기록');if(s.decisionSerial!=null&&(!Number.isInteger(s.decisionSerial)||s.decisionSerial<0))throw Error('손상된 결정 순서');if(s.medicalRng!=null&&!Number.isInteger(s.medicalRng))throw Error('손상된 건강 난수');if(s.resolvedDecisions&&(!Array.isArray(s.resolvedDecisions)||!s.resolvedDecisions.every(x=>typeof x==='string')))throw Error('손상된 선택 기록');}
